import{_ as i,o as t,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Admin Management — Implementation Plan","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/plan.md","filePath":"feature/admin-management/plan.md"}'),o={name:"feature/admin-management/plan.md"};function c(r,e,h,d,l,s){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="admin-management-—-implementation-plan" tabindex="-1">Admin Management — Implementation Plan <a class="header-anchor" href="#admin-management-—-implementation-plan" aria-label="Permalink to &quot;Admin Management — Implementation Plan&quot;">​</a></h1><p>&gt; Thực thi inline theo <code>superpowers:executing-plans</code>, kiểm thử nghiệp vụ theo <code>superpowers:test-driven-development</code>. Người dùng đã duyệt spec và yêu cầu bắt đầu plan/code ngày 2026-10-01. Không cần duyệt lại nghiệp vụ. Không commit hoặc triển khai production trong kế hoạch này.</p><p><strong>Goal:</strong> triển khai 10 FR đã chốt bằng API/dữ liệu thật, bắt đầu từ nền tảng tài khoản và strike; không sửa FR 3.10.3 của Tuấn.</p><p><strong>Spec:</strong> <a href="./confirmed-decisions-2026-10-01.html">quyết định đã duyệt</a>, <code>spec.md</code> trong từng thư mục FR và Word FR 3.10.</p><p><strong>Architecture:</strong> nghiệp vụ Admin nằm trong Business Service hiện có. PostgreSQL giữ tài khoản, strike, yêu cầu xử phạt, audit và email outbox; không tạo microservice mới. UI React dùng Axios/TanStack Query. Publisher kiểm tra lại quyền ở thời điểm dispatch khi luồng version bài viết được nối vào. Mọi thời điểm lưu UTC.</p><p><strong>Tech stack:</strong> Java 21, Spring Boot 3.3.5, JPA/JDBC, PostgreSQL, Redis; React 19, TypeScript, Tailwind, i18next, TanStack Query.</p><h2 id="global-constraints" tabindex="-1">Global Constraints <a class="header-anchor" href="#global-constraints" aria-label="Permalink to &quot;Global Constraints&quot;">​</a></h2><ul><li>Giữ thay đổi đăng nhập/refresh đang có trong working tree. Làm tại workspace người dùng đang mở; không chuyển branch hay bỏ các thay đổi chưa commit.</li><li>System role ADMIN/USER độc lập với quyền Owner/Manager/Creator/Client. Không tự chuyển Owner, không khóa Agency theo user.</li><li>Không xóa tài khoản, không reset TOTP, không tự xác thực email bằng nút Admin, không tự ghi nhận doanh thu.</li><li>Dùng response/error envelope hiện có. DTO whitelist, tuyệt đối không trả entity User chứa passwordHash/OTP/totpSecret.</li><li>Kiểm tra quyền ADMIN tại service từ role hiện tại trong DB, không chỉ dựa vào giao diện hoặc claim cũ.</li><li>Khóa hàng user trước mọi thay đổi strike/sanction; audit và outbox cùng transaction. Thao tác ghi có operationId để chống gửi lặp.</li><li>Chỉ đánh dấu task hoàn tất khi có bằng chứng. Kế hoạch tổng thể không đồng nghĩa toàn bộ FR đã được implement.</li></ul><h2 id="_0-đoi-chieu-nen-tang-đa-đoc-code" tabindex="-1">0. Đối chiếu nền tảng (đã đọc code) <a class="header-anchor" href="#_0-đoi-chieu-nen-tang-đa-đoc-code" aria-label="Permalink to &quot;0. Đối chiếu nền tảng (đã đọc code)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Thành phần</th><th>Hiện trạng</th><th>Quyết định triển khai</th></tr></thead><tbody><tr><td>AdminController</td><td>GET users trả entity User; PUT ban ghi SUSPENDED; chưa có kiểm tra ADMIN riêng</td><td>Thay bằng DTO whitelist và service có kiểm tra quyền. Bỏ route ban cũ để không vượt qua xác nhận mới.</td></tr><tr><td>JwtAuthenticationFilter</td><td>Xác thực chữ ký, chưa kiểm tra trạng thái user/blacklist ở Business</td><td>Bổ sung account/session policy; chỉ access token có role hợp lệ được dùng cho API. Chuẩn hóa authority ROLE_ADMIN/ROLE_USER.</td></tr><tr><td>AuthServiceImpl / OAuthService</td><td>Chỉ chấp nhận ACTIVE</td><td>Cho FLAGGED đăng nhập/refresh; khóa DEACTIVATED và kiểm tra mốc thu hồi token. Giữ luồng self-deactivate riêng.</td></tr><tr><td>DB</td><td>ddl-auto=validate, migration SQL thủ công</td><td>Migration cộng thêm, không rewrite dữ liệu SUSPENDED/DELETED; cần áp dụng trước khi chạy binary mới.</td></tr><tr><td>PostDocument</td><td>Chỉ read model Mongo cho thống kê, chưa có write path/version/scheduler trong Business</td><td>FR 3.10.4 cần xây đường ghi contentVersion và nối producer trước khi nghiệm thu dispatch. Không tạo moderation giả dựa trên seed.</td></tr><tr><td>SubscriptionServiceImpl</td><td>listPlans chưa làm; subscribe hiện cấp ACTIVE ngay; chưa có payment webhook/ledger</td><td>Không lấy thao tác subscribe làm tiền thu. FR 3.10.8/11 cần payment ledger và xác nhận thanh toán, trước khi thay gói tại kỳ mới.</td></tr><tr><td>AdminPage</td><td>users/moderation/stats/health đều từ mock</td><td>Thay tab users bằng API thật trước; các tab còn mock không được ghi nhận đã hoàn thành. Giữ monitoring hiện có.</td></tr></tbody></table><h2 id="_1-tai-khoan-strike-xu-phat-—-fr-3-10-5-6-9" tabindex="-1">1. Tài khoản, strike, xử phạt — FR 3.10.5/6/9 <a class="header-anchor" href="#_1-tai-khoan-strike-xu-phat-—-fr-3-10-5-6-9" aria-label="Permalink to &quot;1. Tài khoản, strike, xử phạt — FR 3.10.5/6/9&quot;">​</a></h2><h3 id="files-va-hop-đong" tabindex="-1">Files và hợp đồng <a class="header-anchor" href="#files-va-hop-đong" aria-label="Permalink to &quot;Files và hợp đồng&quot;">​</a></h3><p>Business paths tương đối <code>brandhub-business-service/src/main/java/com/brandhub/business/</code>:</p><ul><li><code>model/User.java</code>, <code>model/enums/UserStatus.java</code>: FLAGGED/PENDING_VERIFICATION, cleanPeriodEndsAt, tokensRevokedBefore, reactivateAt. Chỉ xử phạt Admin có reactivateAt; không mở tài khoản tự deactivated hoặc SUSPENDED cũ.</li><li><code>model/UserStrike.java</code>, <code>model/SanctionReview.java</code>: mức độ, lý do/category, nguồn quy đổi, operationId, người ghi/gỡ, thời gian hết hạn/gỡ và review PENDING/CONFIRMED/CLOSED.</li><li><code>repository/UserStrikeRepository.java</code>, <code>SanctionReviewRepository.java</code>, <code>UserRepository.java</code>: khóa user bằng PESSIMISTIC_WRITE; truy vấn lịch sử có phân trang; chọn batch user đến hạn.</li><li><code>service/admin/StrikePolicy.java</code>: tính thẻ hiệu lực, quy đổi ba Vàng chưa dùng, reset hạn khi vi phạm thật; Clock truyền vào policy để test biên ngày 30.</li><li><code>service/admin/AdminAccountService.java</code>, <code>AdminAccountQueryService.java</code>, <code>AdminAccountLifecycle.java</code>: guard ADMIN và đối tượng, ghi/gỡ, unflag, xác nhận review còn đủ chứng cứ, thu hồi session, mở lại và audit.</li><li><code>service/admin/AdminEmailOutbox.java</code>: lưu email mở khóa cùng transaction; worker gửi sau commit, retry có backoff. SMTP không bảo đảm exactly-once khi process chết sau gửi trước ghi nhận; ghi rõ giới hạn này.</li><li><code>security/AccountAccessPolicy.java</code>, <code>JwtAuthenticationFilter.java</code>, <code>service/impl/AuthServiceImpl.java</code>, <code>service/OAuthService.java</code>: chặn token trước thu hồi, FLAGGED vẫn đăng nhập. Thêm mốc thu hồi vào refresh; sau mở lại phải login mới.</li><li><code>controller/AdminController.java</code>, <code>dto/request/AdminStrikeRequest.java</code>, <code>AdminSanctionRequest.java</code>, <code>AdminUnflagRequest.java</code>, <code>dto/response/AdminUserResponse.java</code>, <code>AdminStrikeSummary.java</code>: DTO có validation, không rò bí mật.</li><li>Migration: <code>brandhub-infrastructure/docs/database/migrations/2026-10-01-admin-account-strikes.sql</code>. Cập nhật hai init SQL sau khi migration được kiểm chứng. Enum PostgreSQL thêm bằng statement autocommit trước DDL dùng giá trị mới.</li><li>Web: <code>src/services/adminAccountService.ts</code>, <code>src/pages/admin/components/AdminAccountsPanel.tsx</code>, <code>AdminStrikeDialog.tsx</code>, <code>src/pages/admin/index.tsx</code>. Không sử dụng callback verify/delete/toggle-disable từ mock cho tab users mới.</li><li>Locale: <code>src/i18n/locales/{vi,en}/admin.json</code>, đăng ký trong <code>src/i18n/index.ts</code>. Keys <code>admin.accounts.{title,search,status,role,name,email,previous,next,empty,error,retry,manage}</code>, <code>admin.strikes.{title,reason,category,level,add,pardon,unflag,confirm,confirmLabel,ownerImpact,history,cleanUntil,reactivateAt,pendingReview,saved,error}</code>, <code>admin.status.*</code>, <code>admin.level.*</code>.</li></ul><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><ul><li>GET <code>/api/v1/admin/users?page=1&amp;size=20&amp;search=&amp;status=&amp;role=</code> → <code>{items,page,size,total}</code> (size 1–100).</li><li>GET <code>/api/v1/admin/users/{id}/violations?page=1&amp;size=20</code> → summary + lịch sử phân trang.</li><li>POST cùng route → <code>{operationId,action:ADD|REMOVE,level?,category?,strikeId?,reason}</code>. Lặp cùng operationId/payload trả hiện trạng; cùng key khác payload trả 409.</li><li>PATCH <code>/api/v1/admin/users/{id}/status</code> → <code>{action:UNFLAG,reason}</code>; không còn thẻ hiệu lực và không DEACTIVATED mới được bỏ cờ.</li><li>POST <code>/api/v1/admin/users/{id}/sanction</code> → <code>{reviewId,confirmed:true,reason}</code>. Review đang chờ + RED hoặc &gt;=3 ORANGE hiệu lực; tự phạt/ADMIN ngang hàng trả 403.</li><li>Route PUT ban cũ bị loại bỏ, không còn đường bỏ qua review. FLAG từ ORANGE; thao tác FLAG thủ công phải ghi nhận ORANGE có lý do qua violations.</li></ul><h3 id="trinh-tu-red-→-green" tabindex="-1">Trình tự RED → GREEN <a class="header-anchor" href="#trinh-tu-red-→-green" aria-label="Permalink to &quot;Trình tự RED → GREEN&quot;">​</a></h3><ol><li>Test ba Vàng khác category→một Cam, Y4 không thêm Cam, Y6→Cam thứ hai; pardon nguồn giữ Cam; ngày 29 reset, đúng ngày 30 expire, không hồi sinh thẻ cũ.</li><li>Test ADMIN guard, DTO không lộ secret, idempotency, review chỉ một pending, evidence hết hạn không xác nhận được; confirm30 ngày và không tự mở sớm.</li><li>Implement migration, model/repository, policy, service/API; test transactions bằng PostgreSQL dev/integration trước nghiệm thu concurrency.</li><li>Test auth: FLAGGED được login/refresh; refresh/2FA token không dùng làm access; DEACTIVATED bị chặn; token cũ vẫn bị chặn sau auto-unlock; self-deactivated không bị worker mở.</li><li>UI real API: tìm/lọc/phân trang, lịch sử và ghi/gỡ thẻ, xác nhận khóa; giữ form khi lỗi và khóa nút trong mutation. Light/dark + VI/EN.</li><li>Chạy unit/MockMvc, compile/build web, migration trên DB test; ghi nhận các lỗi baseline riêng.</li></ol><h2 id="_2-kich-hoat-va-ho-so-—-fr-3-10-7-8" tabindex="-1">2. Kích hoạt và hồ sơ — FR 3.10.7/8 <a class="header-anchor" href="#_2-kich-hoat-va-ho-so-—-fr-3-10-7-8" aria-label="Permalink to &quot;2. Kích hoạt và hồ sơ — FR 3.10.7/8&quot;">​</a></h2><ul><li>Thêm <code>AdminProvisioningService</code>, DTO <code>CreateAdminUserRequest</code>/<code>UpdateAdminUserRequest</code>, <code>AccountActivationController/Service</code>, bảng <code>account_activation_tokens</code> lưu token hash/expiry/usedAt. GET catalog sử dụng SubscriptionPlanRepository thật.</li><li>POST admin/users: chuẩn hóa unique email, fullname 2–100, mật khẩu min8 + số + ký tự đặc biệt, BCrypt12; PENDING_VERIFICATION + requirePasswordReset; enqueue email bắt buộc. Không đặt verifiedAt hoặc cấp paid entitlement.</li><li>Token kích hoạt chỉ được dùng verify + đổi password; token dùng một lần, chống replay, không trả access trước hoàn tất hai điều kiện. UI <code>/activate-account</code>, lỗi giữ form, không lưu token trong log.</li><li>PATCH admin/users/{id}: email bất biến; role hiện tại kiểm tra lại; không hạ ADMIN ngang hàng. Pending plan lưu <code>subscription_plan_changes</code> gắn currentPeriodEnd, paymentRequired=true; không ghi revenue.</li><li>Test email trùng/normalization, mật khẩu yếu, replay/expiry, OAuth không bỏ qua password reset, Owner profile, kỳ sau chưa trả tiền không được tăng quota.</li></ul><h2 id="_3-noi-dung-va-xuat-ban-—-fr-3-10-4" tabindex="-1">3. Nội dung và xuất bản — FR 3.10.4 <a class="header-anchor" href="#_3-noi-dung-va-xuat-ban-—-fr-3-10-4" aria-label="Permalink to &quot;3. Nội dung và xuất bản — FR 3.10.4&quot;">​</a></h2><ul><li>Xây <code>ContentVersionService</code> với Mongo immutable revision và PostgreSQL <code>content_moderation_reviews</code> (postId + versionId unique, snapshot/hash/reason/decision/adminId). Producer nội dung sở hữu việc enqueue; ADMIN không truyền arbitrary authorId.</li><li><code>AdminModerationController/Service</code>: APPROVE/BLOCK exact version, note &gt;=10, block tạo strike qua cùng service transaction/idempotency key từ review. Approve giữ workflow/schedule hiện có.</li><li>Nối scheduler đọc trạng thái tác giả khi đưa job vào queue; job chứa authorId, postId, contentVersionId. <code>publisher/core/consumer/PublishJobConsumer.java</code> gọi internal eligibility endpoint có credential service trước adapter; fail closed khi không xác minh được. Bài cũ đã schedule được giữ lại, không chỉ chặn UI.</li><li>Test version mismatch, author bị flag sau enqueue, Manager approve không đủ, block sửa/resubmit mới, duplicate callback không ghi strike hai lần, Business unavailable không publish.</li></ul><h2 id="_4-email-broadcasts-—-fr-3-10-1" tabindex="-1">4. Email broadcasts — FR 3.10.1 <a class="header-anchor" href="#_4-email-broadcasts-—-fr-3-10-1" aria-label="Permalink to &quot;4. Email broadcasts — FR 3.10.1&quot;">​</a></h2><ul><li><code>AdminNotificationController/Service</code>, PostgreSQL <code>admin_notifications</code> + recipient deliveries. Các trạng thái DRAFT/SCHEDULED/SENDING/SENT/FAILED/CANCELLED; SENDING là trạng thái kỹ thuật khóa audience và quyền sửa.</li><li>Scheduler claim due rows bằng <code>FOR UPDATE SKIP LOCKED</code>, resolve audience ALL/BY_PLAN/BY_ROLE tại send time. Delivery unique(notificationId,userId), không retry delivered. SMTP retry có backoff và giới hạn log không lộ nội dung nhạy cảm.</li><li>Validate title5–200/body10–5000; future schedule ISO timestamp có offset; timezone hiển thị. PATCH/cancel chỉ trước gửi; zero recipients SENT/0. UI composer/list với lịch và cancel confirmation.</li><li>Test chuyển plan trước gửi, cancel/send race, duplicate worker, SMTP fail/partial, đúng offset và zero audience.</li></ul><h2 id="_5-thong-ke-doanh-thu-—-fr-3-10-2-11" tabindex="-1">5. Thống kê, doanh thu — FR 3.10.2/11 <a class="header-anchor" href="#_5-thong-ke-doanh-thu-—-fr-3-10-2-11" aria-label="Permalink to &quot;5. Thống kê, doanh thu — FR 3.10.2/11&quot;">​</a></h2><ul><li><code>AdminStatisticsService</code> đọc user.lastLoginAt (successful login) và audit LOGIN; audit TOKEN_REFRESH không là activity. Ba rankings riêng: Mongo posts workspace→agency, audit sự kiện nghiệp vụ agencyId (CREATE/UPDATE/DELETE/ROLE_CHANGE/PERMISSION_CHANGE), payment ledger agencyId.</li><li>Xây payment ledger nguồn sự kiện xác nhận giao dịch: unique provider/eventId, type SUBSCRIPTION/AI_CREDIT/REFUND, amount/currency/paidAt/refundOf/agencyId. Cần đầu nối payment provider trước nghiệm thu thu thực tế; không suy đoán giao dịch từ subscription ACTIVE hoặc seed.</li><li><code>AdminRevenueService</code>: BigDecimal, paid active subscription net recurring price/cycleMonths; MRR sum/ARR*12; receipts/partial refunds theo ngày sự kiện; đồng tiền phải nhóm riêng, không cộng VND với USD.</li><li><code>ReportPeriod</code> chỉ UTC/Asia/Ho_Chi_Minh, interval [from,to), daily buckets trong zone; cùng cache key/filter/asOf cho màn và export. Cache 15 phút có asOf.</li><li>UI <code>AdminStatisticsPanel</code>/<code>AdminRevenuePanel</code>; dữ liệu unavailable phải hiển thị rõ, không tráo số mock. Test gói năm1200000→100000MRR, giảm giá, AIcredit, hoàn kỳ khác, timezone midnight, inactive/failedpayment, ba ranking độc lập.</li></ul><h2 id="_6-pdf-—-fr-3-10-12" tabindex="-1">6. PDF — FR 3.10.12 <a class="header-anchor" href="#_6-pdf-—-fr-3-10-12" aria-label="Permalink to &quot;6. PDF — FR 3.10.12&quot;">​</a></h2><ul><li><code>AdminReportController/Service</code> dùng snapshot dataset từ mục5; A4, embedded font có tiếng Việt, filters/zone/asOf và pagination. Không đưa field bí mật user vào report.</li><li>API trả metadata JSON + link download có token hash, expires24h; authorization ADMIN ở cả create/download. File private storage và cleanup TTL; audit export có filter/count, không nội dung cá nhân.</li><li>Không có dữ liệu→MSG122 không tạo file. Test expired link, unauthorized download, dataset/formula parity, tiếng Việt và overflow bảng bằng render PDF.</li></ul><h2 id="verification-baseline" tabindex="-1">Verification / baseline <a class="header-anchor" href="#verification-baseline" aria-label="Permalink to &quot;Verification / baseline&quot;">​</a></h2><ul><li>Business: Maven 3.9.11 từ wrapper cache, <code>mvn -B test</code>; trước sửa 243 tests, 1 failure,10 errors,9 skipped (log <code>.tmp/admin-baseline-tests.log</code>). Phân tích cụ thể trước kết luận regression.</li><li>Web: <code>npm run build</code>, eslint các file đổi; Playwright smoke nếu server chạy. Không có script unit test hiện tại.</li><li>Gateway/Publisher: <code>mvn -B test</code> khi sửa tương ứng.</li><li>Migration: apply DB test, run twice, verify FK/unique indexes, concurrency same-user; backup trước khi apply dev DB. Không tự migrate production.</li></ul><h2 id="review-focus" tabindex="-1">Review Focus <a class="header-anchor" href="#review-focus" aria-label="Permalink to &quot;Review Focus&quot;">​</a></h2><p>Kiểm tra mọi đường cấp/quay vòng JWT, không lộ secret từ DTO, race ghi/gỡ/quy đổi/confirm, không mở self-deactivated hoặc SUSPENDED cũ, không tác động agency members, rollback DB/outbox, SMTP ambiguity; actor authorization lấy từ DB. Review độc lập sau khi hoàn thành slice triển khai, không coi unit mocks chứng minh được khóa DB.</p><h2 id="quyet-đinh-ky-thuat-sau-review-—-2026-10-02" tabindex="-1">Quyết định kỹ thuật sau review — 2026-10-02 <a class="header-anchor" href="#quyet-đinh-ky-thuat-sau-review-—-2026-10-02" aria-label="Permalink to &quot;Quyết định kỹ thuật sau review — 2026-10-02&quot;">​</a></h2><ul><li>Thêm <code>users.row_version</code> (JPA optimistic lock) để thao tác hồ sơ/login cũ không ghi đè xử phạt vừa commit. Xung đột trả <code>409 CONCURRENT_UPDATE</code>.</li><li>Thêm <code>users.session_version</code>; xác nhận xử phạt tăng generation. Access/refresh token đều mang generation của user tại lúc bắt đầu cấp phiên; kiểm tra generation hiện tại ở access và refresh. Token legacy thiếu claim được coi là generation0. Cách này chặn cả refresh đang chạy đồng thời, dù JWT được ký sau mốc thu hồi; mở lại không reset generation.</li><li>Nếu hạn sạch đã qua nhưng worker chưa chạy, reconciliate flag và review dưới khóa user trước khi ghi vi phạm mới. Một Vàng mới không kéo dài cờ Cam đã hết hạn.</li><li>POST/PATCH mutation trả <code>ApiResponse&lt;Void&gt;</code> với data=null; UI invalidate/refetch danh sách và lịch sử sau thành công. Dùng enum <code>ADD/REMOVE/UNFLAG</code>, khác cách viết thường trong API đề xuất ban đầu.</li><li>Bộ DTO hoàn toàn tách entity User. Đọc danh sách giới hạn100; roles/strike/review được lấy theo batch cho cả page.</li><li>SMTP timeout cấu hình tại <code>application.yml</code>; retry outbox không rollback việc mở tài khoản. Không hứa exactly-once SMTP sau crash giữa gửi và commit.</li><li>Thực thi giai đoạn nền tảng: xem <a href="./implementation-status-2026-10-02.html">trạng thái và bằng chứng</a>. Những mục2–6 vẫn là kế hoạch, chưa nghiệm thu.</li></ul>',34)])])}const m=i(o,[["render",c]]);export{g as __pageData,m as default};
